const serversToScanSoftware = `-- name: ServersToScanSoftware :many
SELECT s.id FROM servers s
LEFT JOIN software_hosts h ON h.server_id = s.id
WHERE s.status = 'online'
  AND (h.checked_at IS NULL OR h.checked_at < now() - make_interval(secs => $1::float8))
ORDER BY h.checked_at NULLS FIRST
LIMIT 50
`

// Online servers whose last scan is older than the interval (or never ran).
func (q *Queries) ServersToScanSoftware(ctx context.Context, seconds float64) ([]uuid.UUID, error) {
	rows, err := q.db.Query(ctx, serversToScanSoftware, seconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []uuid.UUID{}
	for rows.Next() {
		var id uuid.UUID
		if err := rows.Scan(&id); err != nil {
			return nil, err
		}
		items = append(items, id)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

